// Extract the response text directly from the native Gemini node output structure
const raw = $input.first().json.text;

if (!raw) {
  return [{ json: { valid: false, error: "no_text_returned", raw: "" } }];
}

// Strip out any markdown fences if Gemini accidentally included them
const cleaned = raw.replace(/```json|```/g, "").trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  // If parsing fails, return the error structure cleanly for debugging
  return [{ json: { valid: false, error: "parse_failed", raw: cleaned } }];
}

// Return the structured object cleanly for downstream nodes
return [{ json: { valid: true, ...parsed } }];
